from src.auth import decide, LoginDecision

class AuthTest(unittest.TestCase):
    def test_active(self):
        self.assertEqual(decide(False), LoginDecision.ALLOW)
    def test_suspended(self):
        self.assertEqual(decide(True), LoginDecision.DENY)

